function applyTheme(theme){const valid=['light','dark','system'].includes(theme)?theme:'system';document.documentElement.dataset.theme=valid;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=valid==='light'?'#f4f6f8':valid==='dark'?'#0b0d12':(matchMedia('(prefers-color-scheme: light)').matches?'#f4f6f8':'#0b0d12');['light','dark','system'].forEach(k=>$('#theme'+k[0].toUpperCase()+k.slice(1))?.classList.toggle('active',k===valid));const status=$('#themeStatus');if(status)status.textContent='Current theme: '+(valid==='system'?'Follow system':valid[0].toUpperCase()+valid.slice(1));}
